css:
.print-format { padding: 0 !important; margin: 0 !important; }
@page { size: 80mm auto; margin: 2mm; }
.tk-receipt { width: 72mm; max-width: 72mm; margin: 0 auto; font-family: "DejaVu Sans Mono", "Courier New", monospace; font-size: 11px; line-height: 1.3; color: #000; }
.tk-receipt table { width: 100%; border-collapse: collapse; }
.tk-receipt td { padding: 0; vertical-align: top; }
.tk-receipt .c { text-align: center; }
.tk-receipt .r { text-align: right; white-space: nowrap; padding-left: 4px; }
.tk-receipt .b { font-weight: bold; }
.tk-receipt .big { font-size: 13px; }
.tk-receipt .small { font-size: 9px; }
.tk-receipt .mt { margin-top: 4px; }
.tk-receipt .rule { border-top: 1px dashed #000; margin: 4px 0; }
.tk-receipt .efris-qr { width: 34mm; height: 34mm; }
.tk-receipt .efris-pending { border: 1px solid #000; padding: 3px; margin: 3px 0; }
.tk-receipt .efris-fdn, .tk-receipt .efris-code { word-break: break-all; white-space: normal; }

html:
{%- set efris = efris_receipt_data(doc) -%}
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
<div class="tk-receipt">
  <div class="c b big">{{ company.company_name }}</div>
  {%- if doc.company_address_display %}<div class="c small">{{ doc.company_address_display | striptags }}</div>{% endif %}
  {%- if efris.tin %}<div class="c">TIN: {{ efris.tin }}</div>{% endif %}
  <div class="c b mt">
    {%- if doc.is_return -%}CREDIT NOTE{%- elif efris.state != "not_efris" -%}FISCAL RECEIPT / TAX INVOICE{%- else -%}RECEIPT{%- endif -%}
  </div>
  <div class="rule"></div>
  <table class="kv">
    <tr><td>{{ _("Receipt") }}</td><td class="r">{{ doc.name }}</td></tr>
    <tr><td>{{ _("Date") }}</td><td class="r">{{ frappe.utils.format_date(doc.posting_date) }} {{ ((doc.posting_time or "")|string)[:8] }}</td></tr>
    <tr><td>{{ _("Customer") }}</td><td class="r">{{ doc.customer_name }}</td></tr>
    <tr><td>{{ _("Cashier") }}</td><td class="r">{{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner }}</td></tr>
    {%- if doc.is_return and doc.return_against %}
    <tr><td>{{ _("Against") }}</td><td class="r">{{ doc.return_against }}</td></tr>
    {%- endif %}
  </table>
  <div class="rule"></div>
  <table class="items">
    {%- for item in doc.items %}
    <tr><td colspan="2" class="b">{{ item.item_name }}</td></tr>
    <tr>
      <td class="small">{{ item.get_formatted("qty") }} {{ item.uom }} x {{ item.get_formatted("rate", doc) }}</td>
      <td class="r">{{ item.get_formatted("amount", doc) }}</td>
    </tr>
    {%- endfor %}
  </table>
  <div class="rule"></div>
  <table class="kv">
    <tr><td>{{ _("Net Total") }}</td><td class="r">{{ doc.get_formatted("net_total") }}</td></tr>
    {%- for tax in doc.taxes %}{% if tax.tax_amount %}
    <tr><td>{{ tax.description }}</td><td class="r">{{ tax.get_formatted("tax_amount", doc) }}</td></tr>
    {%- endif %}{% endfor %}
    {%- if doc.discount_amount %}
    <tr><td>{{ _("Discount") }}</td><td class="r">-{{ doc.get_formatted("discount_amount") }}</td></tr>
    {%- endif %}
    <tr class="b big"><td>{{ _("TOTAL") }}</td><td class="r">{{ doc.get_formatted("rounded_total" if doc.rounded_total else "grand_total") }}</td></tr>
    {%- for p in doc.payments %}{% if p.amount %}
    <tr><td>{{ p.mode_of_payment }}</td><td class="r">{{ p.get_formatted("amount", doc) }}</td></tr>
    {%- if p.reference_no %}
    <tr><td colspan="2">&nbsp;&nbsp;{{ _("Txn ID") }}: {{ p.reference_no | e }}</td></tr>
    {%- endif %}
    {%- endif %}{% endfor %}
    {%- if doc.change_amount %}
    <tr><td>{{ _("Change") }}</td><td class="r">{{ doc.get_formatted("change_amount") }}</td></tr>
    {%- endif %}
  </table>

  {%- if efris.state != "not_efris" %}
  <div class="rule"></div>
  <div class="efris">
    <div class="c b">URA EFRIS</div>
    {%- if efris.state == "fiscalised" %}
    <table class="kv">
      <tr><td>{{ _("FDN") }}</td><td class="r b efris-fdn">{{ efris.fdn }}</td></tr>
      <tr><td>{{ _("Verification Code") }}</td><td class="r b efris-code">{{ efris.verification_code or "" }}</td></tr>
      {%- if efris.device_no %}<tr><td>{{ _("Device No") }}</td><td class="r">{{ efris.device_no }}</td></tr>{% endif %}
      {%- if efris.issued %}<tr><td>{{ _("Issued") }}</td><td class="r">{{ efris.issued }}</td></tr>{% endif %}
      {%- if efris.is_return and efris.original_fdn %}<tr><td>{{ _("Original FDN") }}</td><td class="r">{{ efris.original_fdn }}</td></tr>{% endif %}
    </table>
    {%- if efris.qr %}
    <div class="c mt"><img class="efris-qr" src="{{ efris.qr }}" alt="EFRIS QR code"></div>
    {%- endif %}
    {%- elif efris.state == "credit_note_pending" %}
    <div class="c b efris-pending">{{ _("CREDIT NOTE PENDING URA APPROVAL") }}</div>
    <div class="c small">{{ _("Application Ref") }}: {{ efris.application_ref }}</div>
    {%- if efris.original_fdn %}<div class="c small">{{ _("Original FDN") }}: {{ efris.original_fdn }}</div>{% endif %}
    {%- else %}
    <div class="c b efris-pending">{{ _("EFRIS PENDING") }}</div>
    <div class="c small">{{ _("This receipt has not been fiscalised by URA yet. It is submitted automatically; ask for a reprint to get the FDN and QR code.") }}</div>
    {%- endif %}
    {%- if efris.sandbox %}<div class="c small b">*** {{ _("EFRIS SANDBOX - NOT A VALID TAX INVOICE") }} ***</div>{% endif %}
  </div>
  {%- endif %}
  <div class="rule"></div>
  <div class="c small">{{ _("Thank you!") }}</div>
</div>
